-- Option A pay: each review comment records whether it raised a real issue.
alter table public.walkthrough_reviews add column if not exists raises_issue boolean not null default false;
comment on column public.walkthrough_reviews.raises_issue is 'True when the comment asks for or points out a change (used for Option A pay: bonus per walkthrough with a real issue).';

-- Backfill from a hand-labelled pass over every distinct comment (2026-09-26).
-- Each value is the first 10 hex chars of md5(lowercased, whitespace-collapsed comment)
-- for the 284 distinct comments labelled as asking for a change (718 rows, 148 walkthroughs).
